package io.github.diodeme.ji.storage.sqlite;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.sql.Statement;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Forward-only transactional migrator with a verified pre-migration SQLite backup. */
public final class SqliteMigrationManager {
    private static final DateTimeFormatter BACKUP_TIME = DateTimeFormatter.ofPattern("uuuuMMdd'T'HHmmssSSS'Z'")
            .withZone(ZoneOffset.UTC);
    private final Path database;
    private final String databaseId;
    private final List<SqliteMigration> migrations;
    private final Clock clock;

    public SqliteMigrationManager(Path database, String databaseId, List<SqliteMigration> migrations) {
        this(database, databaseId, migrations, Clock.systemUTC());
    }

    SqliteMigrationManager(Path database, String databaseId, List<SqliteMigration> migrations, Clock clock) {
        if (database == null || databaseId == null || databaseId.isBlank() || migrations == null || clock == null) {
            throw new IllegalArgumentException("SQLite migration configuration is incomplete");
        }
        this.database = database.toAbsolutePath().normalize();
        this.databaseId = databaseId;
        this.migrations = migrations.stream().sorted(Comparator.comparingInt(SqliteMigration::version)).toList();
        this.clock = clock;
        for (int index = 0; index < this.migrations.size(); index++) {
            if (this.migrations.get(index).version() != index + 1) {
                throw new IllegalArgumentException("SQLite migrations must be contiguous from version 1");
            }
        }
    }

    public Result migrate() {
        try {
            Path parent = database.getParent();
            if (parent == null) throw new IOException("database has no parent");
            Files.createDirectories(parent);
            int current = currentVersion();
            int target = migrations.size();
            if (current > target) throw failure("storage.schema_too_new", current, target, null);
            if (current == target) return new Result(target, Optional.empty(), List.of());
            Path backup = createBackup(current);
            var applied = new java.util.ArrayList<Integer>();
            try (Connection connection = DriverManager.getConnection("jdbc:sqlite:" + database)) {
                connection.setAutoCommit(false);
                try {
                    for (SqliteMigration migration : migrations) {
                        if (migration.version() <= current) continue;
                        for (String sql : migration.statements()) {
                            try (Statement statement = connection.createStatement()) { statement.execute(sql); }
                        }
                        try (Statement statement = connection.createStatement()) {
                            statement.execute("PRAGMA user_version=" + migration.version());
                        }
                        applied.add(migration.version());
                    }
                    connection.commit();
                } catch (SQLException | RuntimeException migrationFailure) {
                    connection.rollback();
                    throw failure("storage.migration_failed", current, target, migrationFailure);
                }
            }
            verifyDatabase(database, target);
            return new Result(target, Optional.of(backup), applied);
        } catch (SqliteMigrationException failure) {
            throw failure;
        } catch (IOException | SQLException failure) {
            throw failure("storage.migration_failed", -1, migrations.size(), failure);
        }
    }

    private int currentVersion() throws SQLException {
        try (Connection connection = DriverManager.getConnection("jdbc:sqlite:" + database);
             Statement statement = connection.createStatement();
             var result = statement.executeQuery("PRAGMA user_version")) {
            return result.getInt(1);
        }
    }

    private Path createBackup(int version) throws SQLException, IOException {
        Path backup = database.resolveSibling(database.getFileName() + ".pre-v" + (version + 1) + "-"
                + BACKUP_TIME.format(Instant.now(clock)) + ".backup");
        try (Connection source = DriverManager.getConnection("jdbc:sqlite:" + database);
             Statement statement = source.createStatement()) {
            statement.execute("PRAGMA wal_checkpoint(FULL)");
        }
        Files.copy(database, backup, StandardCopyOption.COPY_ATTRIBUTES);
        verifyDatabase(backup, version);
        return backup;
    }

    private static void verifyDatabase(Path file, int expectedVersion) throws SQLException {
        try (Connection connection = DriverManager.getConnection("jdbc:sqlite:" + file);
             Statement statement = connection.createStatement()) {
            try (var integrity = statement.executeQuery("PRAGMA integrity_check")) {
                if (!integrity.next() || !"ok".equalsIgnoreCase(integrity.getString(1))) {
                    throw new SQLException("SQLite integrity check failed");
                }
            }
            try (var version = statement.executeQuery("PRAGMA user_version")) {
                if (!version.next() || version.getInt(1) != expectedVersion) {
                    throw new SQLException("SQLite schema version verification failed");
                }
            }
        }
    }

    private SqliteMigrationException failure(String code, int current, int target, Throwable cause) {
        return new SqliteMigrationException(code, Map.of(
                "database", databaseId,
                "currentVersion", Integer.toString(current),
                "targetVersion", Integer.toString(target)), cause);
    }

    public record Result(int schemaVersion, Optional<Path> backup, List<Integer> appliedVersions) {
        public Result {
            backup = backup == null ? Optional.empty() : backup;
            appliedVersions = List.copyOf(appliedVersions);
        }
    }
}
